import React, { useEffect, useState } from 'react';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
} from 'react-icons/fi';

import { toast } from 'react-toastify';

import api from '../../services/api';

const AdminLeadership = () => {
  // ==========================================
  // STATE
  // ==========================================
  const [members, setMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [editingMember, setEditingMember] = useState(null);

  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    position: '',
    bio: '',
    email: '',
    phone: '',
    facebook_url: '',
    linkedin_url: '',
    is_active: true,
    order: 0,
  });

  // ==========================================
  // API BASE URL
  // ==========================================
  const API_BASE_URL =
    process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  // ==========================================
  // LOAD DATA
  // ==========================================
  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      setLoading(true);

      const response = await api.get('/api/leadership/');

      setMembers(response.data || []);
    } catch (error) {
      console.error(error);

      toast.error(
        error?.response?.data?.detail ||
          'Failed to load leadership team'
      );
    } finally {
      setLoading(false);
    }
  };

  // ==========================================
  // RESET FORM
  // ==========================================
  const resetForm = () => {
    setFormData({
      name: '',
      position: '',
      bio: '',
      email: '',
      phone: '',
      facebook_url: '',
      linkedin_url: '',
      is_active: true,
      order: 0,
    });

    setEditingMember(null);
    setImageFile(null);
    setImagePreview(null);
  };

  // ==========================================
  // OPEN ADD MODAL
  // ==========================================
  const handleAdd = () => {
    resetForm();
    setShowModal(true);
  };

  // ==========================================
  // OPEN EDIT MODAL
  // ==========================================
  const handleEdit = (member) => {
    setEditingMember(member);

    setFormData({
      name: member.name || '',
      position: member.position || '',
      bio: member.bio || '',
      email: member.email || '',
      phone: member.phone || '',
      facebook_url: member.facebook_url || '',
      linkedin_url: member.linkedin_url || '',
      is_active: member.is_active ?? true,
      order: member.order ?? 0,
    });

    if (member.image) {
      setImagePreview(
        member.image.startsWith('http')
          ? member.image
          : `${API_BASE_URL}${member.image}`
      );
    } else {
      setImagePreview(null);
    }

    setImageFile(null);
    setShowModal(true);
  };

  // ==========================================
  // CLOSE MODAL
  // ==========================================
  const handleCloseModal = () => {
    setShowModal(false);
    resetForm();
  };

  // ==========================================
  // INPUT CHANGE
  // ==========================================
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  // ==========================================
  // IMAGE CHANGE
  // ==========================================
  const handleImageChange = (e) => {
    const file = e.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (!allowedTypes.includes(file.type)) {
      toast.error('Please select JPG, JPEG, PNG or WEBP image');
      e.target.value = '';
      return;
    }

    // 5MB
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image must be less than 5MB');
      e.target.value = '';
      return;
    }

    setImageFile(file);

    const previewUrl = URL.createObjectURL(file);
    setImagePreview(previewUrl);
  };

  // ==========================================
  // REMOVE SELECTED IMAGE
  // ==========================================
  const handleRemoveImage = () => {
    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(imagePreview);
    }

    setImageFile(null);
    setImagePreview(null);
  };

  // ==========================================
  // SUBMIT
  // ==========================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.name.trim()) {
      toast.error('Name is required');
      return;
    }

    if (!formData.position.trim()) {
      toast.error('Position is required');
      return;
    }

    try {
      setSaving(true);

      const data = new FormData();

      data.append('name', formData.name.trim());
      data.append('position', formData.position.trim());

      if (formData.bio) {
        data.append('bio', formData.bio);
      }

      if (formData.email) {
        data.append('email', formData.email);
      }

      if (formData.phone) {
        data.append('phone', formData.phone);
      }

      if (formData.facebook_url) {
        data.append(
          'facebook_url',
          formData.facebook_url
        );
      }

      if (formData.linkedin_url) {
        data.append(
          'linkedin_url',
          formData.linkedin_url
        );
      }

      data.append(
        'is_active',
        String(formData.is_active)
      );

      data.append(
        'order',
        String(formData.order || 0)
      );

      // Upload image file
      if (imageFile) {
        data.append('image', imageFile);
      }

      if (editingMember) {
        await api.put(
          `/api/leadership/${editingMember.id}`,
          data
        );

        toast.success(
          'Leadership member updated successfully'
        );
      } else {
        await api.post(
          '/api/leadership/',
          data
        );

        toast.success(
          'Leadership member added successfully'
        );
      }

      handleCloseModal();
      await fetchMembers();
    } catch (error) {
      console.error(error);

      const detail = error?.response?.data?.detail;

      if (Array.isArray(detail)) {
        toast.error(
          detail[0]?.msg || 'Validation error'
        );
      } else {
        toast.error(
          detail ||
            'Failed to save leadership member'
        );
      }
    } finally {
      setSaving(false);
    }
  };

  // ==========================================
  // DELETE
  // ==========================================
  const handleDelete = async (member) => {
    const confirmed = window.confirm(
      `Are you sure you want to delete "${member.name}"?`
    );

    if (!confirmed) {
      return;
    }

    try {
      await api.delete(
        `/api/leadership/${member.id}`
      );

      toast.success(
        'Leadership member deleted successfully'
      );

      fetchMembers();
    } catch (error) {
      console.error(error);

      toast.error(
        error?.response?.data?.detail ||
          'Failed to delete leadership member'
      );
    }
  };

  // ==========================================
  // IMAGE URL
  // ==========================================
  const getImageUrl = (image) => {
    if (!image) {
      return null;
    }

    if (image.startsWith('http')) {
      return image;
    }

    return `${API_BASE_URL}${image}`;
  };

  // ==========================================
  // LOADING
  // ==========================================
  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center py-5">
        <div
          className="spinner-border text-primary"
          role="status"
        >
          <span className="visually-hidden">
            Loading...
          </span>
        </div>
      </div>
    );
  }

  return (
    <div className="container-fluid py-4">

      {/* ======================================
          HEADER
      ====================================== */}
      <div className="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4">

        <div>
          <h3 className="fw-bold mb-1 d-flex align-items-center gap-2">
            <FiUsers />
            Leadership Team
          </h3>

          <p className="text-muted mb-0">
            Manage your school's leadership team.
          </p>
        </div>

        <button
          type="button"
          className="btn btn-primary d-flex align-items-center gap-2"
          onClick={handleAdd}
        >
          <FiPlus />
          Add Member
        </button>
      </div>

      {/* ======================================
          CARD
      ====================================== */}
      <div className="card border-0 shadow-sm">
        <div className="card-body p-0">

          {members.length === 0 ? (
            <div className="text-center py-5">

              <FiUsers
                size={50}
                className="text-muted mb-3"
              />

              <h5>No Leadership Members</h5>

              <p className="text-muted">
                Add your first leadership team member.
              </p>

              <button
                className="btn btn-primary"
                onClick={handleAdd}
              >
                <FiPlus className="me-2" />
                Add Member
              </button>
            </div>
          ) : (
            <div className="table-responsive">

              <table className="table table-hover align-middle mb-0">

                <thead className="table-light">
                  <tr>
                    <th className="ps-4">#</th>
                    <th>Photo</th>
                    <th>Name</th>
                    <th>Position</th>
                    <th>Contact</th>
                    <th>Status</th>
                    <th>Order</th>

                    <th className="text-end pe-4">
                      Actions
                    </th>
                  </tr>
                </thead>

                <tbody>
                  {members.map((member, index) => (
                    <tr key={member.id}>

                      <td className="ps-4">
                        {index + 1}
                      </td>

                      {/* IMAGE */}
                      <td>
                        {member.image ? (
                          <img
                            src={getImageUrl(member.image)}
                            alt={member.name}
                            width="55"
                            height="55"
                            style={{
                              objectFit: 'cover',
                              borderRadius: '50%',
                            }}
                          />
                        ) : (
                          <div
                            className="bg-light d-flex align-items-center justify-content-center"
                            style={{
                              width: 55,
                              height: 55,
                              borderRadius: '50%',
                            }}
                          >
                            <FiUsers
                              size={22}
                              className="text-muted"
                            />
                          </div>
                        )}
                      </td>

                      {/* NAME */}
                      <td>
                        <div className="fw-semibold">
                          {member.name}
                        </div>

                        {member.email && (
                          <small className="text-muted">
                            {member.email}
                          </small>
                        )}
                      </td>

                      {/* POSITION */}
                      <td>
                        {member.position}
                      </td>

                      {/* CONTACT */}
                      <td>
                        {member.phone ? (
                          <span>
                            {member.phone}
                          </span>
                        ) : (
                          <span className="text-muted">
                            —
                          </span>
                        )}
                      </td>

                      {/* STATUS */}
                      <td>
                        {member.is_active ? (
                          <span className="badge bg-success">
                            Active
                          </span>
                        ) : (
                          <span className="badge bg-secondary">
                            Inactive
                          </span>
                        )}
                      </td>

                      {/* ORDER */}
                      <td>
                        {member.order}
                      </td>

                      {/* ACTION */}
                      <td className="text-end pe-4">

                        <button
                          type="button"
                          className="btn btn-sm btn-outline-primary me-2"
                          onClick={() =>
                            handleEdit(member)
                          }
                          title="Edit"
                        >
                          <FiEdit2 />
                        </button>

                        <button
                          type="button"
                          className="btn btn-sm btn-outline-danger"
                          onClick={() =>
                            handleDelete(member)
                          }
                          title="Delete"
                        >
                          <FiTrash2 />
                        </button>

                      </td>
                    </tr>
                  ))}
                </tbody>

              </table>
            </div>
          )}

        </div>
      </div>

      {/* ======================================
          MODAL
      ====================================== */}
      {showModal && (
        <>
          <div
            className="modal fade show d-block"
            tabIndex="-1"
          >
            <div className="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">

              <div className="modal-content border-0 shadow">

                {/* MODAL HEADER */}
                <div className="modal-header">

                  <h5 className="modal-title fw-bold">
                    {editingMember
                      ? 'Edit Leadership Member'
                      : 'Add Leadership Member'}
                  </h5>

                  <button
                    type="button"
                    className="btn"
                    onClick={handleCloseModal}
                  >
                    <FiX size={22} />
                  </button>

                </div>

                {/* FORM */}
                <form onSubmit={handleSubmit}>

                  <div className="modal-body p-4">

                    <div className="row g-4">

                      {/* ========================
                          IMAGE
                      ======================== */}
                      <div className="col-12">

                        <label className="form-label fw-semibold">
                          Member Photo
                        </label>

                        <div className="d-flex flex-wrap align-items-center gap-3">

                          {imagePreview ? (
                            <img
                              src={imagePreview}
                              alt="Preview"
                              width="110"
                              height="110"
                              style={{
                                objectFit: 'cover',
                                borderRadius: '12px',
                              }}
                            />
                          ) : (
                            <div
                              className="border bg-light d-flex align-items-center justify-content-center"
                              style={{
                                width: 110,
                                height: 110,
                                borderRadius: 12,
                              }}
                            >
                              <FiUsers
                                size={35}
                                className="text-muted"
                              />
                            </div>
                          )}

                          <div>

                            <label className="btn btn-outline-primary d-inline-flex align-items-center gap-2">
                              <FiUpload />
                              Choose Image

                              <input
                                type="file"
                                accept="image/png,image/jpeg,image/webp"
                                hidden
                                onChange={
                                  handleImageChange
                                }
                              />
                            </label>

                            {imagePreview && (
                              <button
                                type="button"
                                className="btn btn-outline-danger ms-2"
                                onClick={
                                  handleRemoveImage
                                }
                              >
                                Remove
                              </button>
                            )}

                            <div className="small text-muted mt-2">
                              JPG, PNG or WEBP. Max 5MB.
                            </div>

                          </div>
                        </div>

                      </div>

                      {/* NAME */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Name
                          <span className="text-danger">
                            {' '}*
                          </span>
                        </label>

                        <input
                          type="text"
                          name="name"
                          className="form-control"
                          value={formData.name}
                          onChange={handleChange}
                          placeholder="Enter member name"
                          required
                        />

                      </div>

                      {/* POSITION */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Position
                          <span className="text-danger">
                            {' '}*
                          </span>
                        </label>

                        <input
                          type="text"
                          name="position"
                          className="form-control"
                          value={formData.position}
                          onChange={handleChange}
                          placeholder="e.g. School Director"
                          required
                        />

                      </div>

                      {/* EMAIL */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Email
                        </label>

                        <input
                          type="email"
                          name="email"
                          className="form-control"
                          value={formData.email}
                          onChange={handleChange}
                          placeholder="example@email.com"
                        />

                      </div>

                      {/* PHONE */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Phone
                        </label>

                        <input
                          type="text"
                          name="phone"
                          className="form-control"
                          value={formData.phone}
                          onChange={handleChange}
                          placeholder="012 345 678"
                        />

                      </div>

                      {/* FACEBOOK */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Facebook
                        </label>

                        <input
                          type="text"
                          name="facebook_url"
                          className="form-control"
                          value={
                            formData.facebook_url
                          }
                          onChange={handleChange}
                          placeholder="Facebook profile URL"
                        />

                      </div>

                      {/* LINKEDIN */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          LinkedIn
                        </label>

                        <input
                          type="text"
                          name="linkedin_url"
                          className="form-control"
                          value={
                            formData.linkedin_url
                          }
                          onChange={handleChange}
                          placeholder="LinkedIn profile URL"
                        />

                      </div>

                      {/* ORDER */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold">
                          Display Order
                        </label>

                        <input
                          type="number"
                          name="order"
                          min="0"
                          className="form-control"
                          value={formData.order}
                          onChange={handleChange}
                        />

                      </div>

                      {/* ACTIVE */}
                      <div className="col-md-6">

                        <label className="form-label fw-semibold d-block">
                          Status
                        </label>

                        <div className="form-check form-switch mt-2">

                          <input
                            className="form-check-input"
                            type="checkbox"
                            id="leadershipActive"
                            name="is_active"
                            checked={
                              formData.is_active
                            }
                            onChange={handleChange}
                          />

                          <label
                            className="form-check-label"
                            htmlFor="leadershipActive"
                          >
                            {formData.is_active
                              ? 'Active'
                              : 'Inactive'}
                          </label>

                        </div>

                      </div>

                      {/* BIO */}
                      <div className="col-12">

                        <label className="form-label fw-semibold">
                          Biography
                        </label>

                        <textarea
                          name="bio"
                          className="form-control"
                          rows="5"
                          value={formData.bio}
                          onChange={handleChange}
                          placeholder="Write a short biography..."
                        />

                      </div>

                    </div>
                  </div>

                  {/* MODAL FOOTER */}
                  <div className="modal-footer">

                    <button
                      type="button"
                      className="btn btn-light"
                      onClick={handleCloseModal}
                      disabled={saving}
                    >
                      Cancel
                    </button>

                    <button
                      type="submit"
                      className="btn btn-primary"
                      disabled={saving}
                    >
                      {saving ? (
                        <>
                          <span
                            className="spinner-border spinner-border-sm me-2"
                            role="status"
                          />
                          Saving...
                        </>
                      ) : editingMember ? (
                        'Update Member'
                      ) : (
                        'Add Member'
                      )}
                    </button>

                  </div>

                </form>

              </div>
            </div>
          </div>

          {/* MODAL BACKDROP */}
          <div
            className="modal-backdrop fade show"
            onClick={handleCloseModal}
          />
        </>
      )}

    </div>
  );
};

export default AdminLeadership;
